begin;
select no_plan();
insert into auth.users(id,email,is_anonymous) values ('43000000-0000-4000-8000-000000000001','m43@test.local',false),('43000000-0000-4000-8000-000000000002','s43@test.local',false);
insert into public.profiles(id,display_name) values ('43000000-0000-4000-8000-000000000001','Master43'),('43000000-0000-4000-8000-000000000002','Support43') on conflict do nothing;
insert into public.platform_roles(user_id,role) values ('43000000-0000-4000-8000-000000000001','master'),('43000000-0000-4000-8000-000000000002','support');
delete from public.platform_settings where key in ('max_photos_per_event','reveal_email_sender');
delete from public.feature_flags where key in ('photo_comments','reveal_emails');
select set_config('request.jwt.claims','{"sub":"43000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"support"}}',true);
set local role authenticated;
select is(public.admin_master_config()->'maxPhotosPerEvent','null'::jsonb,'não inventa teto onde não há configuração');
select is(public.get_revela_features()->'commentsEnabled','true'::jsonb,'comentários ativos por padrão, como antes');
select is(public.get_revela_features()->'revealEmailsEnabled','true'::jsonb,'avisos ativos por padrão, como antes');
select throws_ok($$select public.admin_set_master_config('{"commentsEnabled":false}','Motivo válido de teste')$$,'MM004','forbidden','support só lê configurações');
reset role;
select set_config('request.jwt.claims','{"sub":"43000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"master"}}',true);
set local role authenticated;
select throws_ok($$select public.admin_set_master_config('{"commentsEnabled":false}','curto')$$,'MM011',null,'configuração exige motivo');
select throws_ok($$select public.admin_set_master_config('{"commentsEnabled":false}',repeat('x',501))$$,'MM011',null,'motivo limitado no servidor');
select throws_ok($$select public.admin_set_master_config('{"maxPhotoBytes":8388609}','Motivo válido de teste')$$,'MM005','invalid','não aumenta limite além do processamento de 8 MB');
select throws_ok($$select public.admin_set_master_config('{"senderEmail":"invalido"}','Motivo válido de teste')$$,'MM005','invalid','remetente inválido recusado');
select throws_ok($$select public.admin_set_master_config('{"maxPhotosPerEvent":0}','Motivo válido de teste')$$,'MM005','invalid','teto zero recusado');
select throws_ok($$select public.admin_set_master_config('{"commentsEnabled":"false"}','Motivo válido de teste')$$,'MM005','invalid','chave precisa booleano');
select throws_ok($$select public.admin_set_master_config('{"inesperada":true}','Motivo válido de teste')$$,'MM005','invalid','chave não prevista recusada');
select lives_ok($$select public.admin_set_master_config('{"maxPhotosPerEvent":1,"maxPhotoBytes":1048576,"senderEmail":" Envio@Exemplo.com ","commentsEnabled":false,"revealEmailsEnabled":false}','Motivo válido de teste')$$,'lote válido gravado atomicamente');
select is(public.admin_master_config()->>'senderEmail','envio@exemplo.com','remetente normalizado');
select is((public.get_revela_features()->>'maxPhotoBytes')::bigint,1048576::bigint,'limite público reflete bucket real');
select ok(not public.get_revela_features()?'senderEmail','leitura de convidado não recebe remetente privado');
reset role;
select is((select file_size_limit from storage.buckets where id='event-photos'),1048576::bigint,'grava limite efetivo no Storage');
insert into public.events(id,title,category,host_id,host_name,duration_hours,capacity,shots_per_person,start_at) values ('43000000-0000-4000-8000-000000000100','Evento43','festa','43000000-0000-4000-8000-000000000001','Teste',6,10,36,now());
insert into public.photos(id,event_id,author_id,author_name,storage_path) values ('43000000-0000-4000-8000-000000000200','43000000-0000-4000-8000-000000000100','43000000-0000-4000-8000-000000000001','Teste','43000000-0000-4000-8000-000000000100/43000000-0000-4000-8000-000000000200');
select throws_ok($$insert into public.photos(id,event_id,author_id,author_name,storage_path) values ('43000000-0000-4000-8000-000000000201','43000000-0000-4000-8000-000000000100','43000000-0000-4000-8000-000000000001','Teste','43000000-0000-4000-8000-000000000100/43000000-0000-4000-8000-000000000201')$$,'MM020','photoeventlimit','teto aplicado pelo banco a novas reservas');
select lives_ok($$update public.photos set upload_status='pronta' where id='43000000-0000-4000-8000-000000000200'$$,'finalizar reserva ativa não conta duas vezes');
insert into public.photos(id,event_id,author_id,author_name,storage_path,upload_status) values ('43000000-0000-4000-8000-000000000202','43000000-0000-4000-8000-000000000100','43000000-0000-4000-8000-000000000001','Teste','43000000-0000-4000-8000-000000000100/43000000-0000-4000-8000-000000000202','falhou');
select throws_ok($$update public.photos set upload_status='enviando' where id='43000000-0000-4000-8000-000000000202'$$,'MM020','photoeventlimit','reserva falha não fura teto ao retomar por UPDATE');
select throws_ok($$insert into public.photo_comments(photo_id,event_id,author_id,author_name,body) values ('43000000-0000-4000-8000-000000000200','43000000-0000-4000-8000-000000000100','43000000-0000-4000-8000-000000000001','Teste','Comentário')$$,'MM019','commentsdisabled','desligar comentários afeta a escrita real');
insert into public.reveal_email_queue(event_id,user_id,email,optout_token,event_title,event_code) values ('43000000-0000-4000-8000-000000000100','43000000-0000-4000-8000-000000000001','m43@test.local',gen_random_uuid(),'Evento43','TEST43');
select is((select count(*) from public.reveal_email_queue where event_id='43000000-0000-4000-8000-000000000100'),0::bigint,'desligar avisos impede novo enfileiramento');
set local role authenticated;
select lives_ok($$select public.admin_set_master_config('{"maxPhotosPerEvent":null,"commentsEnabled":true,"revealEmailsEnabled":true}','Motivo válido de teste')$$,'reativa recursos e retira teto sem alterar contratos antigos');
reset role;
select lives_ok($$insert into public.photos(id,event_id,author_id,author_name,storage_path) values ('43000000-0000-4000-8000-000000000201','43000000-0000-4000-8000-000000000100','43000000-0000-4000-8000-000000000001','Teste','43000000-0000-4000-8000-000000000100/43000000-0000-4000-8000-000000000201')$$,'teto nulo preserva limites individuais anteriores');
select ok(exists(select 1 from public.audit_logs where actor_id='43000000-0000-4000-8000-000000000001' and action='admin.photo_size_changed' and reason='Motivo válido de teste'),'limite de bucket auditado');
select ok(exists(select 1 from public.audit_logs where actor_id='43000000-0000-4000-8000-000000000001' and target_id='photo_comments' and reason='Motivo válido de teste'),'chave de comentários auditada pela tabela existente');
select ok(not has_function_privilege('anon','public.admin_master_config()','execute'),'anon sem configurações master');
select ok(not has_function_privilege('authenticated','public.reveal_email_delivery_config()','execute'),'só worker consulta remetente');
select ok(has_function_privilege('service_role','public.reveal_email_delivery_config()','execute'),'worker recebe política de entrega');
select * from finish();
rollback;
